    sol = json.load(f)
jobs = {j['job_id']: j for j in sol['jobs']}
if 'J1' in jobs and 'J3' in jobs:
    if jobs['J1']['end'] > jobs['J3']['start']:
        print('PRECEDENCE VIOLATION: J1 ends after J3 starts')
    else:
        print('Precedence OK')
else:
    print('Missing J1 or J3')
