python3 -c "
import csv, json
with open('/app/data/jobs.csv') as f:
    proc_data = {r['job_id']: float(r['proc_min']) for r in csv.DictReader(f)}
with open('/app/solution.json') as f:
    sol = json.load(f)
for j in sol['jobs']:
    if abs(j['proc'] - proc_data[j['job_id']]) > 1e-6:
        print(f'PROC MISMATCH for {j["job_id"]}: expected {proc_data[j["job_id"]]}, got {j["proc"]}')
    if abs(j['end'] - (j['start'] + j['proc'])) > 1e-6:
        print(f'END CALC ERROR for {j["job_id"]}')
print('Proc and End checks complete')
"

